using System;
using System.IO;
using System.Security.Cryptography;
using System.ComponentModel;
using System.Collections.ObjectModel;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Threading;

public enum FileCollision { Skip, Rename, Replace, Cancel }
public sealed class FileTransfer : INotifyPropertyChanged {
 public event PropertyChangedEventHandler PropertyChanged; public readonly Server Device; public readonly bool Upload; public readonly string Source,Destination,DestinationRoot; public readonly bool Replace; public readonly long Total; public CancellationTokenSource CancelSource=new CancellationTokenSource(); public string State{get;set;} public string Detail{get;set;} public double Progress{get;set;} public string Label{get{return (Upload?"↑ ":"↓ ")+Path.GetFileName(Source);}} public string Target{get{return Device.Name+" · "+Destination;}} public string Summary{get{return State+" · "+Detail;}}
 internal string CopyHash;internal DateTime CopyStamp;public bool CanUndo{get{return !Running&&State=="已完成"&&!Replace&&CopyHash!=null;}}
 internal readonly object Gate=new object(); internal int Attempt;internal volatile bool Running; public bool IsRunning{get{return Running;}} public int AttemptCount{get{lock(Gate)return Attempt;}}
 public FileTransfer(Server s,bool upload,string src,string dst,bool replace,long total,string destinationRoot=null){Device=s.Copy();Upload=upload;Source=src;Destination=dst;DestinationRoot=destinationRoot;Replace=replace;Total=total;State="排队";Detail=FileTools.Size(total);}
 public void Notify(){if(PropertyChanged!=null){PropertyChanged(this,new PropertyChangedEventArgs("Progress"));PropertyChanged(this,new PropertyChangedEventArgs("Summary"));PropertyChanged(this,new PropertyChangedEventArgs("IsRunning"));PropertyChanged(this,new PropertyChangedEventArgs("CanUndo"));}}
}
public sealed class FileTransferQueue : IDisposable {
 readonly SemaphoreSlim pool=new SemaphoreSlim(2); readonly Dispatcher ui; bool disposed; public readonly ObservableCollection<FileTransfer> Items=new ObservableCollection<FileTransfer>();public event Action Completed;
 public FileTransferQueue(Dispatcher dispatcher){ui=dispatcher;}
 public void Add(FileTransfer item){if(disposed||Items.Contains(item))return;Items.Insert(0,item);Start(item,false);}
 public void Retry(FileTransfer item){Start(item,true);}
 void Start(FileTransfer item,bool retry){int attempt;CancellationToken token;lock(item.Gate){if(disposed||item.Running)return;if(retry){if(item.State!="失败"&&item.State!="已取消")return;item.CancelSource.Dispose();item.CancelSource=new CancellationTokenSource();}item.Running=true;attempt=++item.Attempt;token=item.CancelSource.Token;item.State="排队";item.Detail=FileTools.Size(item.Total);item.Progress=0;}item.Notify();Run(item,attempt,token);}
 void Post(Action callback){if(!ui.HasShutdownStarted)ui.BeginInvoke(callback);}
 void Update(FileTransfer x,int attempt,string state,string detail,double progress){if(ui.HasShutdownStarted)return;Post((Action)(()=>{lock(x.Gate){if(x.Attempt!=attempt||!x.Running)return;x.State=state;x.Detail=detail;x.Progress=progress;}x.Notify();}));}
 async void Run(FileTransfer job,int attempt,CancellationToken token){bool entered=false;string part=null,finalState="失败",finalDetail="任务未完成";double finalProgress=0;FileConnection remote=null,local=null;try{await pool.WaitAsync(token).ConfigureAwait(false);entered=true;Update(job,attempt,"连接中",job.Target,0);remote=new FileConnection(job.Device);local=new FileConnection(new Server{IsLocal=true,Name="本机"});await remote.Connect(token).ConfigureAwait(false);await local.Connect(token).ConfigureAwait(false);var from=job.Upload?local:remote;var to=job.Upload?remote:local;
 token.ThrowIfCancellationRequested();long length=from.Length(job.Source);DateTime stamp=from.Stamp(job.Source);if(length!=job.Total)throw new IOException("源文件大小已改变，请重新加入队列。");if(to.Device.IsLocal&&job.DestinationRoot!=null)FileTools.EnsureUnderRoot(job.DestinationRoot,job.Destination);string parent=FileTools.Parent(to.Device.IsLocal,job.Destination);to.MakeDirectory(parent);part=job.Destination+".aq-"+Guid.NewGuid().ToString("N")+".part";long done=0;var clock=Stopwatch.StartNew();long last=0;
 using(var hash=SHA256.Create())using(var input=from.OpenRead(job.Source))using(var output=to.OpenNew(part)){byte[] buffer=new byte[131072];int n;while((n=await input.ReadAsync(buffer,0,buffer.Length,token).ConfigureAwait(false))>0){await output.WriteAsync(buffer,0,n,token).ConfigureAwait(false);hash.TransformBlock(buffer,0,n,buffer,0);done+=n;if(clock.ElapsedMilliseconds-last>=120){last=clock.ElapsedMilliseconds;Update(job,attempt,"传输中",FileTools.Size(done)+" / "+FileTools.Size(length)+" · "+FileTools.Size((long)(done/Math.Max(.1,clock.Elapsed.TotalSeconds)))+"/s",length==0?0:100.0*done/length);}}await output.FlushAsync(token).ConfigureAwait(false);hash.TransformFinalBlock(new byte[0],0,0);job.CopyHash=Convert.ToBase64String(hash.Hash);}
 token.ThrowIfCancellationRequested();if(done!=length||to.Length(part)!=length||from.Length(job.Source)!=length||from.Stamp(job.Source)!=stamp)throw new IOException("传输校验失败：源文件发生变化或长度不一致。");if(!job.Replace&&to.Exists(job.Destination))throw new IOException("目标刚被其他任务创建；为保护文件，未覆盖。请重试并处理重名。");if(to.Device.IsLocal&&job.DestinationRoot!=null)FileTools.EnsureUnderRoot(job.DestinationRoot,job.Destination);to.Commit(part,job.Destination,job.Replace);part=null;if(!job.Replace)job.CopyStamp=to.Stamp(job.Destination);finalState="已完成";finalDetail=FileTools.Size(done)+" · "+clock.Elapsed.TotalSeconds.ToString("0.0")+" 秒";finalProgress=100;if(job.Replace)finalDetail+=" · 覆盖任务不可撤销";
 }catch(OperationCanceledException){finalState="已取消";finalDetail="已停止；可从头重试";}catch(Exception ex){finalState=token.IsCancellationRequested?"已取消":"失败";finalDetail=ex.Message;}
 finally{if(part!=null&&remote!=null&&local!=null){Update(job,attempt,"清理中","正在删除本次临时文件",0);try{(job.Upload?remote:local).RemoveOwnPart(part);}catch{finalState="失败";finalDetail="临时文件待清理："+part;}}try{if(remote!=null)remote.Dispose();}catch{}try{if(local!=null)local.Dispose();}catch{}if(entered)pool.Release();string state=finalState,detail=finalDetail;double progress=finalProgress;if(ui.HasShutdownStarted){lock(job.Gate){if(job.Attempt==attempt)job.Running=false;}}else Post((Action)(()=>{lock(job.Gate){if(job.Attempt!=attempt)return;job.State=state;job.Detail=detail;job.Progress=progress;job.Running=false;}job.Notify();if(state=="已完成"&&Completed!=null)Completed();}));}}
 public void Undo(FileTransfer job){int attempt;lock(job.Gate){if(disposed||!job.CanUndo)return;job.Running=true;attempt=++job.Attempt;job.State="撤销中";job.Detail="正在核对副本";}job.Notify();UndoRun(job,attempt);}
 async void UndoRun(FileTransfer job,int attempt){string state="已完成",detail="";bool entered=false;try{await pool.WaitAsync().ConfigureAwait(false);entered=true;await Task.Run(async()=>{using(var dest=new FileConnection(job.Upload?job.Device:new Server{IsLocal=true,Name="本机"})){await dest.Connect(CancellationToken.None).ConfigureAwait(false);if(dest.Device.IsLocal&&job.DestinationRoot!=null)FileTools.EnsureUnderRoot(job.DestinationRoot,job.Destination);dest.UndoCopy(job.Destination,job.CopyHash,job.CopyStamp,job.Total);}}).ConfigureAwait(false);state="已撤销";detail="已删除本次副本；源文件保留";}catch(Exception ex){detail="未撤销："+ex.Message;}finally{if(entered)pool.Release();string finalState=state,finalDetail=detail;Post((Action)(()=>{lock(job.Gate){if(job.Attempt!=attempt)return;job.State=finalState;job.Detail=finalDetail;job.Running=false;if(finalState=="已撤销")job.Progress=0;}job.Notify();if(Completed!=null)Completed();}));}}
 public void Dispose(){disposed=true;foreach(var job in Items)if(job.IsRunning)job.CancelSource.Cancel();}
}

